llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Halofantrine, the closest structural analogue, has low and erratic oral bioavailability in humans and animals; this poor-absorption phenotype is directly relevant to the query's similarly lipophilic, poorly soluble dibutylamino alcohol scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "In a comparative human study, halofantrine oral bioavailability was judged low because peak plasma concentrations after an 8-fold higher oral dose were similar to those after intravenous dosing, implying F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Zotepine, a lipophilic tricyclic amine with a chlorophenyl and aminoether, has an absolute oral bioavailability of only 7-13%, providing affirmative low-F evidence for a structurally related lipophilic amine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A retrospective estimate placed halofantrine absolute F at approximately 30% in fasted humans, which is above the 20% threshold and therefore contradictory to a low prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic, poorly soluble dibutylamino fluorene alcohol (lumefantrine-like). The closest analogue halofantrine is consistently described as having low and erratic oral bioavailability, with comparative IV/oral data suggesting F below 20%; a related lipophilic tricyclic amine (zotepine) has F 7-13%. Although one retrospective halofantrine estimate was ~30%, the weight of transferable experimental evidence and the unfavorable solubility/lipophilicity profile support F <20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Halofantrine absolute F estimates vary between ~30% and qualitative 'low' assessments, creating uncertainty around the 20% threshold.",
    "Food effects and formulation could shift absorption across the 20% threshold.",
    "Non-halofantrine analogues have low Morgan similarity, limiting their transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

